-- Mulgore and Camp Narache: creature abilities
-- Almost none of the zone's creatures had AI; they only melee'd. Port their abilities from the Cataclysm data, and from the classic
-- data where Cataclysm has none (Palemane Tanner, Venture Co. Taskmaster, Flatland Cougar). Orno Grimtotem keeps his Baine event
-- and the Agitated Earth Spirits their soothing script. The Armored Battleboar only takes its Boar Charge: the rest of its Cataclysm
-- rows are a Throw Torch script that needs a flee action and a spell 5.4.8 does not have.

SET @ENTRIES := '2949,2950,2951,2952,2955,2956,2957,2958,2959,2960,2962,2963,2964,2965,2966,2969,2970,2971,2972,2973,2974,2976,2977,2978,2979,3035,3051,3056,3058,3068,3210,3211,3212,3213,3214,3217,3219,3220,3221,3222,3223,3232,3566,5785,5786,5787,5807,10599,10600,34886,36696,36697,36708,36825,36827,36828,36832,36845,36931,37175,37178,43599,43613,43720';

UPDATE `creature_template` SET `AIName` = 'SmartAI' WHERE FIND_IN_SET(`entry`, @ENTRIES);
DELETE FROM `smart_scripts` WHERE `source_type` = 0 AND FIND_IN_SET(`entryorguid`, @ENTRIES);
